class Solution {
public:
    vector<int> kthSmallestPrimeFraction(vector<int>& arr, int k) {
        int n = arr.size();
        double left = 0.0, right = 1.0;
        while (true) {
            double mid = (left + right) / 2.0;
            int count = 0;
            int best_p = 0, best_q = 1;
            int i = 0;
            for (int j = 1; j < n; j++) {
                while (i < j && arr[i] <= mid * arr[j]) i++;
                count += i;
                if (i > 0 && 1LL * arr[i - 1] * best_q > 1LL * best_p * arr[j]) {
                    best_p = arr[i - 1];
                    best_q = arr[j];
                }
            }
            if (count == k) return {best_p, best_q};
            else if (count < k) left = mid;
            else right = mid;
        }
    }
};

